# Conceptual nginx reverse-proxy config, not executed in this environment (would require a running nginx instance and backend servers):
# nginx.conf --
upstream backend_servers {
  least_conn;
  server 10.0.1.10:3000;
  server 10.0.1.11:3000;
  server 10.0.1.12:3000;
}
server {
  listen 443 ssl;
  location / {
    proxy_pass http://backend_servers;
  }
}

# main.tf -- a minimal example (provider/resource syntax)
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_instance" "web" {
  ami           = "ami-0abcdef1234567890"
  instance_type = "t3.micro"
  tags = {
    Name = "web-server"
  }
}

# terraform init      -- downloads the aws provider plugin
# terraform plan      -- shows exactly what would be created, without creating it
# terraform apply     -- actually creates the EC2 instance described above

# Conceptual tagging convention (matches the earlier Terraform example's tags block):
resource "aws_instance" "web" {
  ami           = "ami-0abcdef1234567890"
  instance_type = "t3.micro"
  tags = {
    Name        = "web-server"
    team        = "payments"
    environment = "staging"
    project     = "checkout-redesign"
  }
}
# With consistent tags like this applied to every resource, a cloud cost dashboard
# can break down spend by team/environment/project instead of one opaque total.
